    def wallet_transfers(
        self,
        forward_pagination: Union[Optional[ForwardPaginationInput], UnsetType] = UNSET,
    ) -> WalletTransfers:
        query = gql("""
            query WalletTransfers($forwardPagination: ForwardPaginationInput = null) {
              wallet_transfers(forwardPagination: $forwardPagination) {
                edges {
                  cursor
                  node {
                    ...WalletTransferFields
                    amount {
                      ...MoneyFields
                    }
                    from {
                      ...PersonPublicFields
                    }
                    to {
                      ...PersonPublicFields
                    }
                  }
                }
                pageInfo {
                  endCursor
                  hasNextPage
                  hasPreviousPage
                  startCursor
                }
                totalCount
              }
            }

            fragment MoneyFields on Money {
              currency
              value
            }

            fragment PersonPublicFields on PersonPublic {
              deliveryPromise
              id
              steamAvatar
              steamId
              steamLevel
              steamName
              steamRegisteredAt
            }

            fragment WalletTransferFields on WalletTransfer {
              comment
              completedAt
              createdAt
              id
              status
            }
            """)
        variables: dict[str, object] = {"forwardPagination": forward_pagination}
        response = self.execute(
            document=query,
            operation_name="WalletTransfers",
            variables=variables,
            operation_type="query",
        )
        data = self.get_data(response)
        return self._decode(WalletTransfers, data)

